    termsOfLaw: ['Rápido', 'Lento', 'Gravetos', 'Pedras', 'Papel', 'Pano', 'Sangue', 'Pregos', 'Pele', 'Fundas ou Balas', 'Flechas', 'Lâminas', 'Sólido', 'Líquido', 'Metal', 'Macio', 'Afiado', 'Peso', 'Luz', 'Terra', 'Fogo', 'Água', 'Ar', 'Proibido', 'Puxado', 'Repelido'],
