// Localized accessor for a domain-trace's structured fields.
function domainTraceField(key, field) {
  var dt = DOMAIN_TRACES[key];
  if (!dt) return '';
  var pt = currentLang === 'pt';
  return (pt && dt[field + 'Pt'] != null) ? dt[field + 'Pt'] : (dt[field] || '');
}

