// Resolve an official entry into a full enemy object (handles sinTemplate refs)
// Resolve an official entry into a full enemy object (handles sinTemplate refs).
// forView=true also attaches the template's domain options (for the read-only
// bestiary view); duplication leaves domains empty so the GM picks their own.
function resolveOfficialEnemy(o, forView) {
  if (o.sinTemplate) {
    var s = createSinFromType(o.sinTemplate);
    s.officialId = o.officialId; // preserve for translation lookups in the view
    s.name = o.name;
    s.category = o.category != null ? o.category : s.category;
    s.expansion = o.expansion || 'base';
    if (o.image) s.image = o.image;
    if (o.examplesImage) s.examplesImage = o.examplesImage;
    if (o.examples) s.examples = o.examples;
    if (forView) {
      var tpl = SIN_TEMPLATES[o.sinTemplate] || {};
      s.domains = (tpl.domainOptions || []).map(function(d) { return { name: d.name, description: d.description }; });
    }
    return s;
  }
  return JSON.parse(JSON.stringify(o));
}

/** Factory for a blank Sin (full model, pg. 102-109) */
function createBlankSin() {
  return {
    id: generateId(),
    kind: 'sin',
    version: 1,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    name: '',
    sinType: 'ogre',         // ogre | idol | hound | centipede | toad | lord | other
    form: 'I',               // I (Severed) | II (Fused) | III (Bound)
    category: 2,             // CAT
    primaryEmotion: '',      // e.g. Despair
    appearance: '',          // appearance & psychophysiology
    behavior: '',            // how it acts / fights / speaks
    palace: '',              // location/appearance of the palace
    talismanSegments: 8,     // execution talisman (Sins are typically 8)
    domains: [               // three domains (core powers)
      { name: '', description: '' },
      { name: '', description: '' },
      { name: '', description: '' }
    ],
    traumas: [               // three trauma questions + the Admin's answers
      { question: '', answer: '' },
      { question: '', answer: '' },
      { question: '', answer: '' }
    ],
    attacksWith: '',         // "Attacks with" line
    complications: '',       // complications list
    threats: '',             // threats list
    afflictions: '',         // afflictions (numbered list, freeform)
    tensionMoves: '',        // custom tension moves (one per line)
    severeAttack: '',        // the sin's severe attack
    pressureName: '',        // name of the pressure mechanic (e.g. Miasma)
    pressureEffect: '',      // what happens as pressure rises
    outOfControl: '',        // effect when pressure hits 6+ (beyond +1 CAT)
    palace: '',              // location/appearance of the palace
    traces: '',              // lesser sins / minions
    extraRules: '',          // extra rules block (e.g. Perfect Sin rules/complications)
    expansion: 'base'
  };
}

/** Build a new sin pre-filled from a template type (or blank if type is 'custom'/unknown) */
function createSinFromType(typeId) {
  var s = createBlankSin();
  var tpl = SIN_TEMPLATES[typeId];
  if (!tpl) return s; // custom / unknown -> blank
  s.sinType = typeId;
  s.primaryEmotion = tpl.primaryEmotion || '';
  // Templates store trauma questions as strings; map into question/answer pairs
  var tq = tpl.traumas && tpl.traumas.length ? tpl.traumas.slice(0, 3) : [];
  s.traumas = [0, 1, 2].map(function(i) { return { question: tq[i] || '', answer: '' }; });
  s.palace = tpl.palace || '';
  s.pressureName = tpl.pressureName || '';
  s.pressureEffect = tpl.pressureEffect || '';
  s.outOfControl = tpl.outOfControl || '';
  s.traces = tpl.traces || '';
  s.attacksWith = tpl.attacksWith || '';
  s.complications = tpl.complications || '';
  s.threats = tpl.threats || '';
  s.afflictions = tpl.afflictions || '';
  s.tensionMoves = tpl.tensionMoves || '';
  s.severeAttack = tpl.severeAttack || '';
  return s;
}

/**
 * Build a Perfect Sin of the given base type: the base sin plus the perfect
 * upgrades and global rules folded into editable fields, with the perfect
 * talisman (12 base) and CAT bumped to the 3+ minimum. Returns a sin object.
 */
// Perfect Sin base execution talisman: 12, except the Perfect Idol whose "Mock"
// upgrade sets its base to 6. Total scales as base + 2xCAT (+2xpressure live).
function perfectSinTalismanBase(typeId) {
  return typeId === 'idol' ? 6 : 12;
}

function createPerfectSinFromType(typeId, opts) {
  var s = createSinFromType(typeId);
  var ps = PERFECT_SINS.sins.find(function(x) { return x.baseSinType === typeId; });
  s.name = ps ? ps.name : ('Perfect ' + tSinType(typeId));
  if (ps && ps.image) s.image = ps.image;
  var cat = (opts && opts.category != null) ? opts.category : (s.category || 0);
  if (cat < 3) cat = 3;
  if (cat > 6) cat = 6;
  s.category = cat;
  // Base (12, or 6 for the Idol) + 2xCAT; GM adds +2xpressure live.
  s.talismanSegments = perfectSinTalismanBase(typeId) + 2 * cat;
  var pt = currentLang === 'pt';
  var pfx = pt ? '[Perfeito] ' : '[Perfect] ';
  // Distribute each upgrade into its matching sheet field (slot); everything else
  // (global rules + shared complications + unslotted upgrades) goes to extraRules.
  function appendField(field, text) { s[field] = (s[field] ? s[field] + '\n' : '') + text; }
  var slotMap = { severeAttack: 'severeAttack', threats: 'threats', complications: 'complications', behavior: 'behavior', traces: 'traces', pressure: 'outOfControl' };
  var extraLines = [];
  (ps ? ps.upgrades : []).forEach(function(u) {
    var line = pfx + (pt && u.namePt ? u.namePt : u.name) + ': ' + (pt ? u.pt : u.en);
    var field = slotMap[u.slot];
    if (field) appendField(field, line); else extraLines.push('\u2022 ' + (pt && u.namePt ? u.namePt : u.name) + ': ' + (pt ? u.pt : u.en));
  });
  // Global Perfect Sin rules + shared complications always go to extraRules.
  var rulesTxt = PERFECT_SINS.rules.map(function(r) { return '\u2022 ' + (pt ? r.pt : r.en); }).join('\n');
  var compTxt = PERFECT_SINS.complications.map(function(c) { return '\u2022 ' + (pt ? c.namePt : c.name) + ': ' + (pt ? c.pt : c.en); }).join('\n');
  s.extraRules = (pt ? 'PECADO PERFEITO\n' : 'PERFECT SIN\n') +
    (extraLines.length ? extraLines.join('\n') + '\n\n' : '') +
    (pt ? 'Regras:\n' : 'Rules:\n') + rulesTxt + '\n\n' +
    (pt ? 'Complicações (começa com uma ativa; ativa outra de graça com talismã <=50%):\n' : 'Complications (starts with one active; activates another free at <=50% talisman):\n') + compTxt;
  return s;
}

function getAllEnemies() {
  // Return cached cloud data if available
  if (cloudEnemiesCache !== null) {
    return cloudEnemiesCache;
  }
  
  // Fallback to localStorage
  try {
    var data = localStorage.getItem(ENEMY_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (e) { return []; }
}

/**
 * Get all enemies async - prefers cloud
 */
async function getAllEnemiesAsync() {
  if (isCloudReady() && window.CainFirebase.getCurrentGmProfileId()) {
    try {
      var enemies = await window.CainFirebase.getEnemies();
      cloudEnemiesCache = enemies;
      return enemies;
    } catch (e) {
      console.error('[Storage] Cloud enemies fetch failed:', e);
    }
  }
  return getAllEnemies();
}

// Cloud enemies cache
var cloudEnemiesCache = null;

function getEnemy(id) {
  return getAllEnemies().find(function(en) { return en.id === id; }) || null;
}

function saveEnemy(enemy) {
  var enemies = getAllEnemies();
  var index = enemies.findIndex(function(en) { return en.id === enemy.id; });
  enemy.updatedAt = new Date().toISOString();
  if (index >= 0) { enemies[index] = enemy; } else { enemies.push(enemy); }
  localStorage.setItem(ENEMY_STORAGE_KEY, JSON.stringify(enemies));
  
  // Also save to cloud if available and GM profile is selected
  if (isCloudReady() && window.CainFirebase.getCurrentGmProfileId()) {
    window.CainFirebase.saveEnemy(enemy).then(function() {
      cloudEnemiesCache = null;
    }).catch(function(e) {
      console.error('[Storage] Cloud enemy save failed:', e);
    });
  }
}

function deleteEnemy(id) {
  var enemies = getAllEnemies().filter(function(en) { return en.id !== id; });
  localStorage.setItem(ENEMY_STORAGE_KEY, JSON.stringify(enemies));
  
  // Also delete from cloud if available
  if (isCloudReady()) {
    window.CainFirebase.deleteEnemy(id).then(function() {
      cloudEnemiesCache = null;
    }).catch(function(e) {
      console.error('[Storage] Cloud enemy delete failed:', e);
    });
  }
}

function exportEnemy(enemy) {
  var blob = new Blob([JSON.stringify(enemy, null, 2)], { type: 'application/json' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url; a.download = (enemy.name || 'enemy') + '_cain_enemy.json';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function exportAllEnemies() {
  var enemies = getAllEnemies();
  var blob = new Blob([JSON.stringify(enemies, null, 2)], { type: 'application/json' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url; a.download = 'cain_all_enemies.json';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function importEnemy() {
  return new Promise(function(resolve, reject) {
    var input = document.createElement('input');
    input.type = 'file'; input.accept = '.json';
    input.addEventListener('change', function(e) {
      var file = e.target.files[0];
      if (!file) { reject(new Error('No file selected')); return; }
      var reader = new FileReader();
      reader.onload = function(event) {
        try {
          var data = JSON.parse(event.target.result);
          if (Array.isArray(data)) {
            data.forEach(function(en) { if (en.id && en.name !== undefined) saveEnemy(en); });
            resolve(data);
          } else if (data.id && data.name !== undefined) {
            saveEnemy(data); resolve(data);
          } else { reject(new Error('Invalid enemy file format')); }
        } catch (err) { reject(new Error('Failed to parse JSON file')); }
      };
      reader.onerror = function() { reject(new Error('Failed to read file')); };
      reader.readAsText(file);
    });
    input.click();
  });
}

// ════════════════════════════════════════════════════════════════════
// ROUTER
// ════════════════════════════════════════════════════════════════════

var routes = {};

function route(path, handler) { routes[path] = handler; }

// ── Scroll persistence ──────────────────────────────────────────────
// Remember each page's scroll position so that:
//  • navigating forward to a sub-page starts at the top;
//  • navigating back (browser Back) restores where you were.
var scrollPositions = {};          // hash -> scrollY of the page when we left it
var lastHash = window.location.hash.slice(1) || 'home';

function currentScroll() {
  return window.pageYOffset || document.documentElement.scrollTop || 0;
}

function navigate(path) {
  // Save the scroll of the page we're leaving so we can restore it if we return.
  scrollPositions[lastHash] = currentScroll();
  window.location.hash = path;
}

function initRouter() {
  window.addEventListener('hashchange', handleRoute);
  handleRoute();
}

function handleRoute() {
  var hash = window.location.hash.slice(1) || 'home';
  var parts = hash.split('/');
  var path = parts[0];
  var params = parts.slice(1);
  if (routes[path]) { routes[path].apply(null, params); }
  else if (routes['home']) { routes['home'](); }

  // If we have a remembered position for this hash (we left it earlier and are
  // now returning), restore it and consume it (so a later fresh visit starts at
  // the top); otherwise start at the top. Wait a frame so the freshly-rendered
  // DOM has its full height before scrolling.
  var saved = scrollPositions[hash];
  if (saved != null) {
    delete scrollPositions[hash];
    requestAnimationFrame(function() { window.scrollTo(0, saved); });
  } else {
    window.scrollTo(0, 0);
  }
  lastHash = hash;
}

